import { Component, inject } from '@angular/core';
import { ActivatedRoute } from '@angular/router';
import { AutorizacionesListComponent } from '../../../shared/components/autorizaciones-list/autorizaciones-list.component';

const STATUS_PRESET_MAP: Record<string, string[]> = {
  'por-evaluar': ['Enviada', 'Incompleta', 'Subsanada'],
  'en-analisis': ['En Análisis'],
  'en-firma': ['En Firma'],
  'terminadas': ['Terminada'],
  'no-autorizadas': ['No Autorizada'],
};

const TITLE_MAP: Record<string, string> = {
  'por-evaluar': 'Trámites por evaluar',
  'en-analisis': 'Trámites en análisis',
  'en-firma': 'Trámites en firma',
  'terminadas': 'Trámites terminados',
  'no-autorizadas': 'Trámites no autorizados',
};

@Component({
  selector: 'app-ejecutivos-tramites',
  imports: [AutorizacionesListComponent],
  templateUrl: './tramites.component.html',
})
export class TramitesComponent {
  private readonly route = inject(ActivatedRoute);

  readonly presetKey = this.route.snapshot.data?.['statusPreset'] ?? 'por-evaluar';

  readonly presetStatuses: string[] = STATUS_PRESET_MAP[this.presetKey] ?? [];

  readonly presetTitle: string = TITLE_MAP[this.presetKey] ?? 'Trámites';
}
